    if(state && state.turn!==side) reasons.push('not '+side+' turn');
    if(state && state.pending && !(state.pending.type==='tribute_target' && state.pending.card_id===cardId)) reasons.push('another action pending');
    if(state && state.phase!=='Reform') reasons.push('wrong phase');
    if(!isSkillCard(c)) reasons.push('not a Skill Card');
    if(c.tribute && c.tribute.can_be_tributed===false) reasons.push('card cannot be tributed');
