    if(state && isUltimateCard(c) && !hasMatchingClassShard(state,side,c)) reasons.push('Ultimate Tribute requires 1 matching '+({Warrior:'Red',Mage:'Blue',Archer:'Green',Cleric:'White',Thief:'Yellow'}[manaClassFromCardCode(cardId)]||'Color')+' Mana Shard in your Mana Pool');
    if(state && isSkillCard(c) && !legalTributeTargetLanesFor(state,side,cardId).length) reasons.push('no legal receiving hero');
