        appState.pending={type:'target_selection', decision_side:'PLAYER', card_id:p.card_id, hand_index:p.hand_index, source_side:'PLAYER', source_lane:lane, source_card_id:heroIdFrom(sideHeroes(appState,'PLAYER')[lane]), target_side:targetSideForActor(c,'PLAYER'), legal_targets:legalTargetLanesFor(appState,'PLAYER',p.card_id,lane)};
        pushLog(appState,'Choose target for '+cardName(c)+'.'); render(); return true;
