        s.aiDifficulty='intermediate';s.playerHeroes.CENTER.card_id=sourceHero||'S0-THF-H003';
        s.aiHeroes.CENTER.hp=hp;s.aiHeroes.CENTER.maxHp=120;s.aiHeroes.CENTER.statuses=[];
