  function bindMobileHandLongPress(el){
    if(!el||el._glMobileLongPressBound)return;
    el._glMobileLongPressBound=true;
    var timer=null,startX=0,startY=0,pointerId=null,triggered=false;
    function clearTimer(){if(timer){clearTimeout(timer);timer=null;}}
    function cancelPreview(){clearTimer();if(triggered)v59HandHoverZoomHide(el);triggered=false;pointerId=null;}
    el.addEventListener('contextmenu',function(ev){ev.preventDefault();});
    el.addEventListener('dragstart',function(ev){ev.preventDefault();});
    var image=el.querySelector&&el.querySelector('img');if(image){image.draggable=false;if(image.setAttribute)image.setAttribute('draggable','false');}
    el.addEventListener('pointerdown',function(ev){
      if(ev.pointerType==='mouse'||!isMobileViewport())return;
      clearTimer();pointerId=ev.pointerId;startX=Number(ev.clientX||0);startY=Number(ev.clientY||0);triggered=false;
      timer=setTimeout(function(){timer=null;triggered=v59HandHoverZoomShow(el.getAttribute('data-preview'),el);if(triggered)el._glSuppressClickUntil=Date.now()+650;},360);
    });
    el.addEventListener('pointermove',function(ev){
      if(pointerId===null||ev.pointerId!==pointerId)return;
      if(Math.abs(Number(ev.clientX||0)-startX)>10||Math.abs(Number(ev.clientY||0)-startY)>10)cancelPreview();
    });
    el.addEventListener('pointerup',cancelPreview);
    el.addEventListener('pointercancel',cancelPreview);
    el.addEventListener('lostpointercapture',cancelPreview);
    el.addEventListener('click',function(ev){if(Number(el._glSuppressClickUntil||0)>Date.now()){ev.preventDefault();ev.stopPropagation();if(typeof ev.stopImmediatePropagation==='function')ev.stopImmediatePropagation();el._glSuppressClickUntil=0;}},true);
  }
