      decks.PLAYER=pv.deck;decks.AI=av.deck;cancelAITurnDirector();clearTransientUiState();
      appState=buildInitialMatchState();matchStarted=true;setupError='';
      firstSide=firstSide==='AI'?'AI':'PLAYER';
