      s=fresh('S0-CLE-H003');s.aiHeroes.LEFT.card_id='S0-MAG-H001';s.aiHeroes.CENTER.card_id='S0-MAG-H001';s.playerHeroes.LEFT.hp=20;s.playerHeroes.CENTER.hp=100;s.aiHand=['S0-CLE-018','S0-MAG-003'];a=chooseSetup(s);if(!a||a.card_id!=='S0-CLE-018')return{ok:false,reason:'Enemy-target reevaluation setup not produced'};var lane=a.target_lane;executeAIAction(s,a);s.playerHeroes.LEFT.hp=0;s.playerHeroes.LEFT.legacy_mode=true;s.playerHeroes.CENTER.hp=100;s.phase='Battle';f=chooseAIAction(s,'Battle');if(!f||f.source_lane!==lane||f.target_lane!=='CENTER')return{ok:false,reason:'Enemy target could not reevaluate after the original target became illegal while preserving setup attacker',follow:f,lane:lane};
