  window.GL_V6919_MANA_COMMIT_RESPONSE_CANCEL_QA_SELF_TEST=function(){
    initCards();
    var oldApp=appState,oldMatch=matchStarted,oldSuppress=SUPPRESS_RENDER;
    function fresh(turn){
      var st=buildInitialMatchState();appState=st;matchStarted=true;
      st.preGame=null;st.openingFlowCompleted=true;st.gameOver=false;st.winner=null;
      st.turn=turn||'PLAYER';st.phase='Deploy';st.round=2;st.pending=null;st.responseWindow=null;
      st.playerHand=[];st.aiHand=[];st.playerDiscard=[];st.aiDiscard=[];st.pvpHumanVsHuman=false;st.aiControl=null;
      return st;
    }
    function setGenericPool(st,side,count,tag){
      var pool=manaPoolCardsForSide(st,side);pool.splice(0,pool.length);
      for(var i=0;i<count;i++)pool.push(makeManaShard('GENERIC','',side,String(tag||'QA')+'-'+(i+1)));
      syncManaCountForSide(st,side);return pool;
    }
    function countOf(list,id){return (list||[]).filter(function(x){return x===id;}).length;}
    function fail(reason,extra){return Object.assign({ok:false,reason:reason},extra||{});}
    try{
      SUPPRESS_RENDER=true;

      // A. Main-card PAY commits exact Shards before the opposing reactive window.
      // PASS later must resolve without a second spend.
      var st=fresh('PLAYER');st.pvpHumanVsHuman=true;st.playerHand=['S0-EVT-001'];st.aiHand=[];
      var pp=setGenericPool(st,'PLAYER',4,'EARLY-P'),selected=pp.slice(0,3).map(function(sh){return sh.uid;});
      if(!commitPlayedCard(st,{card_id:'S0-EVT-001',hand_index:0,side:'PLAYER',source_side:'PLAYER',source_lane:'CENTER',source_card_id:heroIdFrom(st.playerHeroes.CENTER),_mana_choice_complete:true,selected_mana_shard_uids:selected}))return fail('Early-commit setup did not open the Event reactive window');
      if(st.mana!==1||manaPoolCardsForSide(st,'PLAYER').length!==1)return fail('Main Event Mana was not committed before reactive priority',{mana:st.mana,pool:manaPoolCardsForSide(st,'PLAYER').length});
      if(!st.responseWindow||st.responseWindow.kind!=='incoming_card'||!st.responseWindow.action||st.responseWindow.action._mana_payment_committed!==true)return fail('Reactive window did not retain committed-payment marker',{responseWindow:st.responseWindow});
      if(!resolveResponseWindow(null))return fail('PASS did not resume the committed Event');
      if(st.mana!==1||manaPoolCardsForSide(st,'PLAYER').length!==1)return fail('PASS spent the main Event Mana a second time',{mana:st.mana,pool:manaPoolCardsForSide(st,'PLAYER').length});
      if(countOf(st.playerDiscard,'S0-EVT-001')!==1)return fail('Event did not resolve exactly once after PASS',{discard:st.playerDiscard});

      // B. With 4 Mana, paying the 3-Mana incoming Event leaves 1 immediately.
      // The original side therefore cannot counter a paid Intercept costing 2.
      // Response payment CANCEL is pre-commit and restores the original window with no costs spent.
      st=fresh('AI');st.aiHand=['S0-EVT-001','S0-EVT-007'];st.playerHand=['S0-EVT-007'];
      setGenericPool(st,'AI',4,'CANCEL-AI');setGenericPool(st,'PLAYER',2,'CANCEL-P');
      if(!commitPlayedCard(st,{card_id:'S0-EVT-001',hand_index:0,side:'AI',source_side:'AI',source_lane:'CENTER',source_card_id:heroIdFrom(st.aiHeroes.CENTER)}))return fail('AI Event did not open PLAYER reactive window');
      if(st.aiMana!==1||manaPoolCardsForSide(st,'AI').length!==1)return fail('AI Event payment was not authoritative before Intercept choice',{aiMana:st.aiMana,pool:manaPoolCardsForSide(st,'AI').length});
      if(reactiveCancelOptionsFor(st,'Event','AI','PLAYER').length!==0)return fail('Original side can still afford a 2-Mana counter-Intercept from stale pre-payment Mana',{aiMana:st.aiMana,options:reactiveCancelOptionsFor(st,'Event','AI','PLAYER')});
      var opt=(st.responseWindow&&st.responseWindow.options||[]).find(function(o){return o.card_id==='S0-EVT-007';});
      if(!opt)return fail('PLAYER Intercept option missing from original Response Window',{options:st.responseWindow&&st.responseWindow.options});
      if(!resolveResponseWindow(clone(opt)))return fail('Choosing Intercept did not enter payment');
      if(!st.pending||st.pending.type!=='response_payment_choice'||st.pending.committed!==false||st.pending.commit_stage!=='pre_commit_payment')return fail('Response payment is not pre-commit before PAY',{pending:st.pending});
      if(st.mana!==2||countOf(st.playerHand,'S0-EVT-007')!==1)return fail('Choosing Response spent resources before PAY',{playerMana:st.mana,hand:st.playerHand});
      if(!cancelResponsePaymentChoice())return fail('Response payment CANCEL returned false');
      if(st.mana!==2||manaPoolCardsForSide(st,'PLAYER').length!==2)return fail('CANCEL spent Response Mana',{playerMana:st.mana,pool:manaPoolCardsForSide(st,'PLAYER').length});
      if(countOf(st.playerHand,'S0-EVT-007')!==1||countOf(st.playerDiscard,'S0-EVT-007')!==0)return fail('CANCEL moved the Response card out of Hand',{hand:st.playerHand,discard:st.playerDiscard});
      if(st.pending||!st.responseWindow||st.responseWindow.kind!=='incoming_card'||st.responseWindow.selected!=null)return fail('CANCEL did not restore the original selectable Response Window',{pending:st.pending,responseWindow:st.responseWindow});
      opt=(st.responseWindow.options||[]).find(function(o){return o.card_id==='S0-EVT-007';});
      if(!opt||!resolveResponseWindow(clone(opt))||!st.pending||st.pending.type!=='response_payment_choice')return fail('Intercept could not be selected again after CANCEL',{pending:st.pending,responseWindow:st.responseWindow});
      if(!commitResponsePaymentChoice())return fail('Response PAY did not commit Intercept');
      if(st.mana!==0||manaPoolCardsForSide(st,'PLAYER').length!==0)return fail('Response PAY did not spend exactly 2 Mana once',{playerMana:st.mana,pool:manaPoolCardsForSide(st,'PLAYER').length});
      if(st.aiMana!==1||manaPoolCardsForSide(st,'AI').length!==1)return fail('Canceled main Event refunded or double-spent its already committed Mana',{aiMana:st.aiMana,pool:manaPoolCardsForSide(st,'AI').length});
      if(countOf(st.playerDiscard,'S0-EVT-007')!==1||countOf(st.aiDiscard,'S0-EVT-001')!==1)return fail('Committed Intercept / canceled Event destinations are incorrect',{playerDiscard:st.playerDiscard,aiDiscard:st.aiDiscard});
      if(st.pending||st.responseWindow)return fail('Successful Intercept left a Response frame stuck',{pending:st.pending,responseWindow:st.responseWindow});

      // C. Nested Intercept remains functional: the original side may counter only when its
      // post-main-payment pool can actually afford the 2-Mana counter. Every payment occurs once.
      st=fresh('AI');st.aiHand=['S0-EVT-001','S0-EVT-007'];st.playerHand=['S0-EVT-007'];
      setGenericPool(st,'AI',5,'NEST-AI');setGenericPool(st,'PLAYER',2,'NEST-P');
      if(!commitPlayedCard(st,{card_id:'S0-EVT-001',hand_index:0,side:'AI',source_side:'AI',source_lane:'CENTER',source_card_id:heroIdFrom(st.aiHeroes.CENTER)}))return fail('Nested-chain setup Event failed');
      if(st.aiMana!==2)return fail('Nested-chain main Event did not leave exactly 2 Mana',{aiMana:st.aiMana});
      opt=(st.responseWindow&&st.responseWindow.options||[]).find(function(o){return o.card_id==='S0-EVT-007';});
      if(!opt||!resolveResponseWindow(clone(opt))||!st.pending||st.pending.type!=='response_payment_choice')return fail('Nested-chain PLAYER Intercept payment did not open',{pending:st.pending,responseWindow:st.responseWindow});
      if(!commitResponsePaymentChoice())return fail('Nested-chain PLAYER Intercept PAY failed');
      if(st.aiMana!==0||st.mana!==0)return fail('Nested Intercept payments were not each committed exactly once',{aiMana:st.aiMana,playerMana:st.mana});
      if(countOf(st.aiDiscard,'S0-EVT-007')!==1||countOf(st.playerDiscard,'S0-EVT-007')!==1)return fail('Nested Intercepts did not both reach Discard exactly once',{aiDiscard:st.aiDiscard,playerDiscard:st.playerDiscard});
      if(countOf(st.aiDiscard,'S0-EVT-001')!==1)return fail('Underlying Event did not resume/resolve exactly once after nested counter',{aiDiscard:st.aiDiscard});
      if(st.pending||st.responseWindow)return fail('Nested Intercept chain left pending/Response state',{pending:st.pending,responseWindow:st.responseWindow});

      // D. Mandatory additional Response costs are also pre-commit. CANCEL after selecting
      // the extra card must spend/discard nothing; PAY then spends that cost exactly once.
      st=fresh('AI');st.phase='Battle';st.aiHand=['S0-WAR-001'];st.playerHand=['S0-ARC-003','S0-WAR-002'];
      setGenericPool(st,'AI',2,'EXTRA-AI');setGenericPool(st,'PLAYER',0,'EXTRA-P');
      st.aiHeroes.LEFT.card_id='S0-WAR-H001';st.aiHeroes.LEFT.exhausted=false;
      st.playerHeroes.LEFT.card_id='S0-ARC-H001';st.playerHeroes.LEFT.hp=80;st.playerHeroes.LEFT.maxHp=80;st.playerHeroes.LEFT.exhausted=false;
      if(!commitPlayedCard(st,{card_id:'S0-WAR-001',hand_index:0,side:'AI',source_side:'AI',source_lane:'LEFT',source_card_id:heroIdFrom(st.aiHeroes.LEFT),target_side:'PLAYER',target_lane:'LEFT'}))return fail('Additional-cost Response setup Attack failed');
      opt=(st.responseWindow&&st.responseWindow.options||[]).find(function(o){return o.card_id==='S0-ARC-003';});
      if(!opt||!resolveResponseWindow(clone(opt))||!st.pending||st.pending.type!=='response_payment_choice')return fail('Additional-cost Response payment did not open',{pending:st.pending,responseWindow:st.responseWindow});
      var extraPick=(st.pending.candidates||[]).findIndex(function(x){return x.card_id==='S0-WAR-002';});
      if(extraPick<0||!selectResponsePaymentChoice(extraPick))return fail('Additional Response discard candidate missing',{pending:st.pending});
      if(!cancelResponsePaymentChoice())return fail('CANCEL failed after selecting mandatory additional Response cost');
      if(st.playerHand.length!==2||countOf(st.playerHand,'S0-ARC-003')!==1||countOf(st.playerHand,'S0-WAR-002')!==1||st.playerDiscard.length!==0)return fail('CANCEL paid a mandatory additional Response cost',{hand:st.playerHand,discard:st.playerDiscard});
      opt=(st.responseWindow&&st.responseWindow.options||[]).find(function(o){return o.card_id==='S0-ARC-003';});
      if(!opt||!resolveResponseWindow(clone(opt))||!st.pending||st.pending.type!=='response_payment_choice')return fail('Additional-cost Response could not be chosen again after CANCEL',{pending:st.pending,responseWindow:st.responseWindow});
      extraPick=(st.pending.candidates||[]).findIndex(function(x){return x.card_id==='S0-WAR-002';});selectResponsePaymentChoice(extraPick);
      if(!commitResponsePaymentChoice())return fail('Additional-cost Response PAY failed');
      if(st.playerHand.length!==0||countOf(st.playerDiscard,'S0-ARC-003')!==1||countOf(st.playerDiscard,'S0-WAR-002')!==1)return fail('Mandatory additional Response cost was not paid exactly once',{hand:st.playerHand,discard:st.playerDiscard});
      if(st.playerHeroes.LEFT.hp!==80)return fail('Escape Arrow did not resolve after committed additional-cost PAY',{hp:st.playerHeroes.LEFT.hp});
      if(st.pending||st.responseWindow)return fail('Additional-cost Response left pending/Response state',{pending:st.pending,responseWindow:st.responseWindow});

      return{ok:true,version:'v6.91.9',mainManaCommittedBeforeReactiveWindow:true,passNoDoubleSpend:true,staleManaExploitBlocked:true,responseCancelPreCommit:true,responsePayCommitsOnce:true,canceledMainNoRefund:true,nestedIntercept:true,additionalCostCancelAndPay:true};
    }catch(err){return{ok:false,reason:String(err&&err.message||err),stack:String(err&&err.stack||'')};}
    finally{appState=oldApp;matchStarted=oldMatch;SUPPRESS_RENDER=oldSuppress;try{closeChoice();closeResponseWindowUI();}catch(_){}}
  };

